<script lang="ts">
	import { retainedGroupCanClaim } from "$publicApi/group-presentation";
	import AccountFollow from "$publicApi/AccountFollow.svelte";
	import { page } from "$app/state";
	import { PUBLIC_SITE_NAME } from "$env/static/public";
	import { API, Constants, Mutex, Permission } from "$lib";
	import type { UpdateSettingsRequest } from "$lib/API/Settings";
	import { useComments } from "$lib/components/comments/context.svelte";
	import * as ReportDialog from "$lib/components/ReportDialog.svelte";
	import { AspectRatio } from "$lib/components/ui/aspect-ratio";
	import { Button } from "$lib/components/ui/button";
	import { buttonVariants } from "$lib/components/ui/button/button.svelte";
	import * as Dialog from "$lib/components/ui/dialog";
	import ImageLoader from "$lib/components/ui/ImageLoader.svelte";
	import { Spinner } from "$lib/components/ui/spinner";
	import { setChaptersCount, setGroup } from "$lib/Context";
	import { Session } from "$lib/stores";
	import { prefs } from "$lib/stores/prefs.js";
	import { cn } from "$lib/Utils";
	import {
		BanIcon,
		CrownIcon,
		FilesIcon,
		FlagIcon,
		InfoIcon,
		MessagesSquare,
		SettingsIcon,
		UserMinusIcon,
		UserPlusIcon
	} from "@lucide/svelte";
	import { StatusCodes } from "http-status-codes";
	import { onMount } from "svelte";
	import { toast } from "svelte-sonner";
	import { createMutationOwner } from "$platform/authenticated-mutation";
	import { applyAccountPreferences, captureAccountPreferences } from "$platform/account-preferences";
	import { createActorFollowState } from "$platform/actor-follow-state";
	import { writable } from "svelte/store";
	import GroupClaimDialog from "$publicApi/PublicGroupClaimDialog.svelte";

	const {
		data,
		children
	}: {
		data: ScanlationGroup;
		children: any;
	} = $props();

	const mutex = new Mutex();
	const group = writable<ScanlationGroup>(data);
	const preferenceOwner = createMutationOwner(() => JSON.stringify([$group.id, page.url.href]));
	const comments = useComments();

	let isGroupClaim = $state(false);
	const followState = createActorFollowState({
		owner: preferenceOwner, mutex,
		target: () => $group.id, lifetime: () => page.url.href,
		canRead: () => false,
		canMutate: () => false,
		read: target => API.Group.GetFollowStatus(target),
		write: (target, followed, intent) => (followed ? API.Group.Follow : API.Group.Unfollow)(target, intent),
		onError: cause => { const error = cause instanceof Constants.Error.Error ? cause : Constants.Error.Unknown; toast.error(error.title, { description: error.body }); }
	});
	let isFollowed = $derived($followState.followed);
	$effect.pre(() => { $group.id; page.url.href; followState.selectTarget(); });
	let isBlocked = $derived($prefs.groups.some(e => e.id === $group.id));
	let chaptersCount = $state<number>();

	setGroup(group);
	setChaptersCount(() => chaptersCount);

	const tabs: Record<
		string,
		{
			name: string;
			icon: any;
			hidden?: boolean;
		}
	> = $derived({
		home: {
			name: "Overview",
			icon: InfoIcon
		},
		uploads: {
			name:
				(chaptersCount ?? $group.relationships?.stats?.chapters)
					? `Uploads (${(chaptersCount ?? $group.relationships?.stats?.chapters)!.toLocaleString()})`
					: `Uploads`,
			icon: FilesIcon
		},
		comments: {
			name: comments.stats?.replies ? `Comments (${comments.stats.replies.toLocaleString()})` : `Comments`,
			icon: MessagesSquare
		},
		settings: {
			name: "Settings",
			icon: SettingsIcon,
			hidden: false
		}
	});

	onMount(async () => {
		if ($group) {
			mutex.exec(async () => {
				try {
					await getChaptersCount();
				} catch (e) {
					console.error(e);
				}
			});
		}
	});

	const getChaptersCount = async () => {
		const q = new URLSearchParams();
		prefs.applyMangaPreferences(q);
		prefs.applyChapterPreferences(q);
		q.set("group", $group.id);
		q.set("limit", "0");

		const res = await API.Chapter.Search(q);
		if (res?.status === StatusCodes.OK && res.body) {
			chaptersCount = res.body.total;
		}
	};

	let isUpdatingFollowStatus = $derived($followState.loading || $followState.updating);
	const updateFollowStatus = () => followState.activate();

	let isUpdatingBlockStatus = $state(false);
	const updateBlockStatus = () => {
		if (mutex.isLocked() || !$Session || (!isBlocked && !followState.knownAbsent())) return;
		const intent = preferenceOwner.capture(), selected = captureAccountPreferences(), target = { id: $group.id, name: $group.name, version: $group.version };
		const next = selected.initial.groups.filter(row => row.id !== target.id);
		if (next.length === selected.initial.groups.length) next.push(target);
		const payload: UpdateSettingsRequest = { version: selected.initial.version, groups: next.map(row => row.id) };
		return mutex.exec(async () => {
			isUpdatingBlockStatus = true;
			try {
				intent.assert(); const res = await API.Settings.Update(payload, intent); intent.assert();
				if (res?.status === StatusCodes.OK && res.body) applyAccountPreferences(selected.actor, selected.authority, res.body, intent);
				else if (res?.status === StatusCodes.TOO_MANY_REQUESTS) throw Constants.Error.TooManyRequests;
				else if (res?.status === StatusCodes.CONFLICT) throw Constants.Error.UpdateConflict;
				else throw Constants.Error.Unknown;
			} catch (cause) { if (!intent.alive()) return; const error = cause instanceof Constants.Error.Error ? cause : Constants.Error.Unknown; toast.error(error.title, { description: error.body }); }
			finally { isUpdatingBlockStatus = false; intent.release(); }
		});
	};
</script>

<svelte:head>
	<title>{$group.name} - {PUBLIC_SITE_NAME}</title>
</svelte:head>

<section class="space-y-2">
	<header class="space-y-5">
		<div class="flex gap-4 md:items-center">
			<div class="w-20 shrink-0">
				<AspectRatio ratio={1 / 1} class="bg-card overflow-hidden rounded-full">
					{#snippet child({ props })}
						<figure {...props}>
							<ImageLoader class="size-full object-cover" src="/images/avatar.webp" />
						</figure>
					{/snippet}
				</AspectRatio>
			</div>
			<div class="flex flex-auto flex-col gap-4 md:w-0 md:flex-row md:items-center">
				<div class="flex-auto md:w-0">
					<h1 class="truncate text-2xl font-semibold">{$group.name}</h1>
					<strong class="text-muted-foreground truncate font-medium">@{$group.id}</strong>
				</div>
				<div class="flex shrink-0 flex-wrap items-center gap-1">
					<AccountFollow kind="group" targetId={$group.id} requestedId={page.params.id??""}/>
					{#if retainedGroupCanClaim($group, !$group.relationships?.members?.some(member => member.is_leader))}
						<Dialog.Root bind:open={isGroupClaim}>
							<Dialog.Trigger class={buttonVariants({ class: "border-none", variant: "outline", size: "sm" })}>
								<CrownIcon />
								Claim
							</Dialog.Trigger>
							<Dialog.Content
								class="flex max-h-[calc(100dvh-2rem)] !max-w-[min(40rem,calc(100dvw-2rem))] flex-col overflow-auto"
							>
								<GroupClaimDialog bind:open={isGroupClaim} group={$group} />
							</Dialog.Content>
						</Dialog.Root>
					{/if}
					{#if false}
						{#if !isBlocked}
							<Button
								class="border-none text-green-300 hover:text-green-400"
								variant="outline"
								size="sm"
								onclick={updateFollowStatus}
								disabled={$mutex || $followState.loading || $followState.updating || (!$followState.ready && !$followState.error)}
							>
								{#if isUpdatingFollowStatus}
									<Spinner />
								{:else if isFollowed}
									<UserMinusIcon />
								{:else}
									<UserPlusIcon />
								{/if}
								{#if $followState.error}
									Retry follow status
								{:else if isFollowed}
									Unfollow
								{:else}
									Follow
								{/if}
							</Button>
						{/if}
						{#if isBlocked || ($followState.ready && !isFollowed)}
							<Button
								class="border-none text-red-300 hover:text-red-400"
								variant="outline"
								size="sm"
								disabled={$mutex}
								onclick={updateBlockStatus}
							>
								<BanIcon />
								{#if isBlocked}
									Unblock
								{:else}
									Block
								{/if}
							</Button>
						{/if}
					{/if}
					<Button
						class="border-none"
						variant="outline"
						size="sm"
						onclick={() => {
							ReportDialog.set($group, Constants.EntityType.ScanlationGroup);
							ReportDialog.open();
						}}
					>
						<FlagIcon />
						Report
					</Button>
				</div>
			</div>
		</div>
		<div class="border-b-2">
			<nav class="text-muted-foreground/80 -mb-0.5 flex flex-nowrap overflow-auto whitespace-nowrap">
				{#each Object.entries(tabs) as [key, item]}
					{#if !item.hidden}
						{@const pathname = key === "home" ? `/group/${$group.id}` : `/group/${$group.id}/${key}`}
						<a
							class={buttonVariants({
								class: cn("border-b-2 border-b-transparent !bg-transparent", {
									"border-accent": page.url.pathname === pathname
								}),
								variant: "ghost"
							})}
							class:!text-accent-foreground={page.url.pathname === pathname}
							href={pathname}
						>
							<item.icon />
							{item.name}
						</a>
					{/if}
				{/each}
			</nav>
		</div>
	</header>
	<div class="space-y-5">
		{@render children?.()}
	</div>
</section>
